#!/bin/bash
# Uninstall script for Mounty for NTFS
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Mounty for NTFS..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Mounty for NTFS if running..."
pkill -f "Mounty for NTFS" 2>/dev/null || true

# Remove /Applications/Mounty.app
echo "Removing /Applications/Mounty.app..."
if [ -d "/Applications/Mounty.app" ]; then
    rm -rf "/Applications/Mounty.app" 2>/dev/null || true
elif [ -f "/Applications/Mounty.app" ]; then
    rm -f "/Applications/Mounty.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.cu4uc.mounty.plist
echo "Removing $HOME/Library/Preferences/com.cu4uc.mounty.plist..."
if [ -d "$HOME/Library/Preferences/com.cu4uc.mounty.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.cu4uc.mounty.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.cu4uc.mounty.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.cu4uc.mounty.plist" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
